# 107 classes; a class id is (0x4 << 16) | its index here (ClassProc 0x4842A802 reads entry id & 0xFFFF, 0x18 bytes each)
.equ PS_Classes_SLOT, 0x4
PS_Classes:
	CLASS	Class_Object, CLASS_Object, PS_Classes, proc=ObjectProc, parent=NOCLASS, allsize=2, selfsize=0, cname=ClassName_Object, sig=ClassSig_Object, fields=ClassFields_Object
